// src/utils/create-geometry-from-polygons.ts
import * as THREE58 from "three";
import { BufferGeometry as BufferGeometry6, Float32BufferAttribute as Float32BufferAttribute6 } from "three";
function createGeometryFromPolygons(polygons) {
  const geometry = new BufferGeometry6();
  const vertices = [];
  const normals = [];
  for (const polygon2 of polygons) {
    for (let i = 1; i < polygon2.vertices.length - 1; i++) {
      vertices.push(
        ...polygon2.vertices[0],
        ...polygon2.vertices[i],
        ...polygon2.vertices[i + 1]
        // Third vertex
      );
      const v1 = new THREE58.Vector3(...polygon2.vertices[0]);
      const v2 = new THREE58.Vector3(...polygon2.vertices[i]);
      const v3 = new THREE58.Vector3(...polygon2.vertices[i + 1]);
      const normal = new THREE58.Vector3().crossVectors(
        new THREE58.Vector3().subVectors(v2, v1),
        new THREE58.Vector3().subVectors(v3, v1)
      ).normalize();
      normals.push(
        normal.x,
        normal.y,
        normal.z,
        normal.x,
        normal.y,
        normal.z,
        normal.x,
        normal.y,
        normal.z
      );
    }
  }
  geometry.setAttribute("position", new Float32BufferAttribute6(vertices, 3));
  geometry.setAttribute("normal", new Float32BufferAttribute6(normals, 3));
  return geometry;
}

